    ["What you are wearing differs from this set. Save puts it into the set."] = "Ce que vous portez diffère de cet ensemble. Enregistrer l'intègre à l'ensemble.",
    ["Which click opens the full picker window. Hovering a slot always shows the compact list, regardless of this setting."] = "Le clic qui ouvre la fenêtre de sélection complète. Le survol d'un emplacement affiche toujours la liste compacte, quel que soit ce réglage.",
    ["Window style"] = "Style des fenêtres",
    ["Wrist"] = "Poignets",
    ["Yes"] = "Oui",
    ["this gem"] = "cette gemme",
    ["|cffaaaaaaA strip with every socket on your equipped gear, hung under the sidebar. Click an empty socket to pick a gem from your bags and set it.|r"] = "|cffaaaaaaUne barre avec chaque châsse de votre équipement porté, placée sous la barre latérale. Cliquez sur une châsse vide pour choisir une gemme dans vos sacs et la sertir.|r",
    ["|cffaaaaaaHover an equipment slot to see the matching items from your bags right next to it, and click one to equip. The click below opens the full window with all of them.|r"] = "|cffaaaaaaSurvolez un emplacement d'équipement pour voir juste à côté les objets correspondants de vos sacs, et cliquez sur l'un d'eux pour l'équiper. Le clic ci-dessous ouvre la fenêtre complète avec tous les objets.|r",
    ["|cffaaaaaaNo gear sets saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaAucun ensemble enregistré pour l'instant. Utilisez le bouton ci-dessus pour enregistrer votre équipement actuel.|r",
    ["|cffaaaaaaOpen the character window to watch the sidebar move while you drag.|r"] = "|cffaaaaaaOuvrez la fenêtre du personnage pour voir la barre bouger pendant que vous faites glisser.|r",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaAstuce : avec la fenêtre du personnage ouverte, activez le mode édition (Déverrouiller) pour faire glisser la barre latérale ; clic droit sur le cadre violet pour réinitialiser sa position.|r",
    ["|cffaaaaaaWhich gear set belongs to a stance, form or spec is chosen per set on the Saved Gear Sets page or in the sidebar's right-click menu.|r"] = "|cffaaaaaaL'ensemble lié à une posture, une forme ou une spé se choisit par ensemble sur la page Ensembles enregistrés ou dans le menu clic droit de la barre latérale.|r",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Erreur lors de la désactivation de '%s' :|r %s",
    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555Erreur lors de l'activation du module '%s' :|r %s",
    ["|cffffd100/vgs back|r — back to the gear you wore before the last switch"] = "|cffffd100/vgs back|r — revenir à l'équipement porté avant le dernier changement",
    ["|cffffd100/vgs bank <name>|r — with the bank open, put the set's pieces from your bags into the bank"] = "|cffffd100/vgs bank <nom>|r — banque ouverte, déposer les pièces de l'ensemble de vos sacs à la banque",
    ["|cffffd100/vgs delete <name>|r — delete a gear set"] = "|cffffd100/vgs delete <nom>|r — supprimer un ensemble",
