    ["|cffffd100/vgs fetch <name>|r — with the bank open, take the set's missing pieces from the bank into your bags"] = "|cffffd100/vgs fetch <nom>|r — banque ouverte, retirer les pièces manquantes de l'ensemble vers vos sacs",
    ["|cffffd100/vgs general|r, |cffffd100sidebar|r, |cffffd100automation|r, |cffffd100slots|r, |cffffd100sets|r, |cffffd100info|r — open that settings page"] = "|cffffd100/vgs general|r, |cffffd100sidebar|r, |cffffd100automation|r, |cffffd100slots|r, |cffffd100sets|r, |cffffd100info|r — ouvrir cette page des paramètres",
    ["|cffffd100/vgs help|r — this list in chat"] = "|cffffd100/vgs help|r — cette liste dans la discussion",
    ["|cffffd100/vgs list|r — list your gear sets in chat"] = "|cffffd100/vgs list|r — lister vos ensembles dans la discussion",
